 {q?.kind==='draw'&&hasAbility(me,'evelyn')&&g.event!=='peyote'&&<>{skill==='evelyn'?<><button className="primary" disabled={!picked.length||picked.length>phaseDrawCount} onClick={()=>send({type:'draw',drawCount:phaseDrawCount-picked.length,cards:picked})}>Выстрелить · {picked.length}, взять карт · {Math.max(0,phaseDrawCount-picked.length)}</button><button onClick={()=>{setSkill(null);setPicked([]);}}>Отмена</button></>:<button onClick={()=>{setSkill('evelyn');setPicked([]);}}>Выстрелы вместо добора</button>}</>}
